def next_smallest_palindrome(n):
    num_str = str(n)
    length = len(num_str)
    mid = length // 2
    digits = [int(d) for d in num_str]

    # Check for the special case where all digits are 9s
    if all(d == 9 for d in digits):
        return int('1' + '0' * (length - 1) + '1')

    # General case - find the next palindrome
    # Start from the middle and work outwards
    for i in range(mid, -1, -1):
        opposite_i = length - i - 1
        if i != opposite_i:
            digits[opposite_i] = digits[i]

    # Increment the middle digit if we're at a boundary case
    if length % 2 == 1:
        digits[mid] += 1
    else:
        digits[mid] += 1
        digits[length - mid - 1] += 1

    # Handle carry-over
    carry = 0
    for i in range(length - 1, -1, -1):
        digits[i] += carry
        if digits[i] > 9:
            digits[i] = 0
            carry = 1
        else:
            carry = 0

    # Convert the list of digits back to an integer
    result = int(''.join(map(str, digits)))

    # Ensure the result is greater than the input
    if result <= n:
        # If not, manually increment the leftmost digit that's not already 9
        for i in range(length):
            if digits[i] < 9:
                digits[i] += 1
                break

    return int(''.join(map(str, digits)))

